export const SDK_FILES: Record<string, string> = {
  "abi.ts": "// The program ABI (design §5.3), byte for byte the same as packages/protocol/src/abi.ts:\n//\n//   run input   : \"TFRN\" u32 version=1 | u32 stage | u32 taskIndex | u32 taskCount | u32 len | input[len]\n//   plan input  : \"TFPL\" u32 version=1 | u32 stage | table params | table hints\n//   plan output : \"TFSS\" u32 version=1 | u8 kind (0 = stage, 1 = done)\n//                 stage: str name | u8 hasCanvas [u32 w u32 h] | u32 n | n × (u32 len input[len] | u8 hasPlace [i32 x y w h])\n//                 done : u8 hasNext [table next]\n//   table       : u32 count | count × (str key | str value)   — values are JSON text, keys sorted\n//   str         : u32 len | utf8[len]\n//\n// Entry points return a pointer to an 8-byte {outPtr: u32, outLen: u32} pair (`emit`).\nimport { ByteReader, ByteWriter } from \"./bytes\";\nimport { Params } from \"./params\";\n\nexport const ABI_VERSION: u32 = 1;\nconst MAGIC_RUN: u32 = 0x4e524654; // \"TFRN\"\nconst MAGIC_PLAN: u32 = 0x4c504654; // \"TFPL\"\nconst MAGIC_SPEC: u32 = 0x53534654; // \"TFSS\"\n\n/** The host allocates input buffers through this; programs re-export it. */\nexport function alloc(len: i32): usize {\n  const size: usize = len > 0 ? <usize>len : 1;\n  return __new(size, idof<ArrayBuffer>());\n}\n\n/** What `run` receives. */\nexport class RunInput {\n  stage: u32 = 0;\n  taskIndex: u32 = 0;\n  taskCount: u32 = 0;\n  input: Uint8Array = new Uint8Array(0);\n}\n\nexport function readRunInput(ptr: usize, len: i32): RunInput {\n  const r = ByteReader.at(ptr, len);\n  if (r.u32() != MAGIC_RUN) abort(\"not a run input\");\n  if (r.u32() != ABI_VERSION) abort(\"unsupported ABI version\");\n  const out = new RunInput();\n  out.stage = r.u32();\n  out.taskIndex = r.u32();\n  out.taskCount = r.u32();\n  out.input = r.blob();\n  return out;\n}\n\n/** What `plan` receives. */\nexport class PlanInput {\n  stage: u32 = 0;\n  params: Params = new Params();\n  hints: Params = new Params();\n}\n\nexport function readPlanInput(ptr: usize, len: i32): PlanInput {\n  const r = ByteReader.at(ptr, len);\n  if (r.u32() != MAGIC_PLAN) abort(\"not a plan input\");\n  if (r.u32() != ABI_VERSION) abort(\"unsupported ABI version\");\n  const out = new PlanInput();\n  out.stage = r.u32();\n  out.params = Params.read(r);\n  out.hints = Params.read(r);\n  return out;\n}\n\nclass TaskEntry {\n  constructor(\n    public input: Uint8Array,\n    public placed: bool,\n    public x: i32,\n    public y: i32,\n    public w: i32,\n    public h: i32,\n  ) {}\n}\n\n/** Builder for the stage a planner returns: `stage(\"render\").canvas(2048, 1280).task(bytes, x, y, w, h)...toBytes()`. */\nexport class Stage {\n  private name: string;\n  private hasCanvas: bool = false;\n  private canvasW: u32 = 0;\n  private canvasH: u32 = 0;\n  private tasks: TaskEntry[] = [];\n\n  constructor(name: string) {\n    this.name = name;\n  }\n\n  canvas(w: u32, h: u32): Stage {\n    this.hasCanvas = true;\n    this.canvasW = w;\n    this.canvasH = h;\n    return this;\n  }\n\n  /** A task with inline input and no placement. */\n  task(input: Uint8Array): Stage {\n    this.tasks.push(new TaskEntry(input, false, 0, 0, 0, 0));\n    return this;\n  }\n\n  /** A task whose output is placed at a rectangle of the canvas (the tiles view). */\n  taskAt(input: Uint8Array, x: i32, y: i32, w: i32, h: i32): Stage {\n    this.tasks.push(new TaskEntry(input, true, x, y, w, h));\n    return this;\n  }\n\n  get taskCount(): i32 {\n    return this.tasks.length;\n  }\n\n  toBytes(): Uint8Array {\n    const w = new ByteWriter(64 + this.tasks.length * 96);\n    w.u32(MAGIC_SPEC).u32(ABI_VERSION).u8(0).str(this.name);\n    if (this.hasCanvas) w.u8(1).u32(this.canvasW).u32(this.canvasH);\n    else w.u8(0);\n    w.u32(<u32>this.tasks.length);\n    for (let i = 0; i < this.tasks.length; i++) {\n      const t = this.tasks[i];\n      w.blob(t.input);\n      if (t.placed) w.u8(1).i32(t.x).i32(t.y).i32(t.w).i32(t.h);\n      else w.u8(0);\n    }\n    return w.toBytes();\n  }\n}\n\nexport function stage(name: string): Stage {\n  return new Stage(name);\n}\n\n/** The planner's \"finished\" answer, with optional params for a follow-up execution. */\nexport function done(next: Params | null): Uint8Array {\n  const w = new ByteWriter(64);\n  w.u32(MAGIC_SPEC).u32(ABI_VERSION).u8(1);\n  if (next === null) w.u8(0);\n  else {\n    w.u8(1);\n    (next as Params).write(w);\n  }\n  return w.toBytes();\n}\n\n/** Hand bytes back to the host: returns the pointer to the {outPtr, outLen} pair the ABI requires. */\nexport function emit(bytes: Uint8Array): usize {\n  const pair = __new(8, idof<ArrayBuffer>());\n  store<u32>(pair, <u32>bytes.dataStart);\n  store<u32>(pair, <u32>bytes.byteLength, 4);\n  return pair;\n}\n",
  "bars.ts": "// The `bars` view payload (design §5.1), byte for byte the same as packages/protocol/src/abi.ts:\n//\n//   bars : \"TFBR\" u32 version=1 | u32 count | count × (str label | f64 value)\n//\n// A `bars` program's final task returns this and the dashboard draws it. Values must be finite:\n// NaN payload bits differ between engines, and twins must agree byte for byte.\nimport { ABI_VERSION } from \"./abi\";\nimport { ByteWriter } from \"./bytes\";\n\nconst MAGIC_BARS: u32 = 0x52424654; // \"TFBR\"\n\nexport class Bars {\n  private labels: string[] = [];\n  private values: f64[] = [];\n\n  bar(label: string, value: f64): Bars {\n    if (isNaN(value) || !isFinite(value)) abort(\"bars: value must be finite\");\n    this.labels.push(label);\n    this.values.push(value);\n    return this;\n  }\n\n  get length(): i32 {\n    return this.labels.length;\n  }\n\n  toBytes(): Uint8Array {\n    const w = new ByteWriter(16 + this.labels.length * 32);\n    w.u32(MAGIC_BARS).u32(ABI_VERSION).u32(<u32>this.labels.length);\n    for (let i = 0; i < this.labels.length; i++) w.str(this.labels[i]).f64(this.values[i]);\n    return w.toBytes();\n  }\n}\n\n/** Builder for a bars payload: `bars().bar(\"the\", 14000).bar(\"of\", 6500).toBytes()`. */\nexport function bars(): Bars {\n  return new Bars();\n}\n",
  "bytes.ts": "// Little-endian byte writer and reader over linear memory. The ABI formats and programs' own\n// compact task inputs are built with these; nothing here depends on the host.\n\nexport class ByteWriter {\n  private buf: ArrayBuffer;\n  private pos: i32 = 0;\n\n  constructor(capacity: i32 = 256) {\n    this.buf = new ArrayBuffer(capacity > 16 ? capacity : 16);\n  }\n\n  get length(): i32 {\n    return this.pos;\n  }\n\n  private ensure(n: i32): void {\n    if (this.pos + n <= this.buf.byteLength) return;\n    let size = this.buf.byteLength * 2;\n    while (size < this.pos + n) size *= 2;\n    const next = new ArrayBuffer(size);\n    memory.copy(changetype<usize>(next), changetype<usize>(this.buf), <usize>this.pos);\n    this.buf = next;\n  }\n\n  u8(v: u8): ByteWriter {\n    this.ensure(1);\n    store<u8>(changetype<usize>(this.buf) + <usize>this.pos, v);\n    this.pos += 1;\n    return this;\n  }\n\n  u32(v: u32): ByteWriter {\n    this.ensure(4);\n    store<u32>(changetype<usize>(this.buf) + <usize>this.pos, v);\n    this.pos += 4;\n    return this;\n  }\n\n  i32(v: i32): ByteWriter {\n    this.ensure(4);\n    store<i32>(changetype<usize>(this.buf) + <usize>this.pos, v);\n    this.pos += 4;\n    return this;\n  }\n\n  f32(v: f32): ByteWriter {\n    this.ensure(4);\n    store<f32>(changetype<usize>(this.buf) + <usize>this.pos, v);\n    this.pos += 4;\n    return this;\n  }\n\n  f64(v: f64): ByteWriter {\n    this.ensure(8);\n    store<f64>(changetype<usize>(this.buf) + <usize>this.pos, v);\n    this.pos += 8;\n    return this;\n  }\n\n  /** Raw bytes, no length prefix. */\n  raw(bytes: Uint8Array): ByteWriter {\n    const n = bytes.byteLength;\n    this.ensure(n);\n    memory.copy(changetype<usize>(this.buf) + <usize>this.pos, bytes.dataStart, <usize>n);\n    this.pos += n;\n    return this;\n  }\n\n  /** u32 length followed by the bytes (the ABI's `bytes`). */\n  blob(bytes: Uint8Array): ByteWriter {\n    this.u32(<u32>bytes.byteLength);\n    return this.raw(bytes);\n  }\n\n  /** u32 byte length followed by UTF-8 (the ABI's `str`). */\n  str(s: string): ByteWriter {\n    const encoded = String.UTF8.encode(s);\n    const n = encoded.byteLength;\n    this.u32(<u32>n);\n    this.ensure(n);\n    memory.copy(changetype<usize>(this.buf) + <usize>this.pos, changetype<usize>(encoded), <usize>n);\n    this.pos += n;\n    return this;\n  }\n\n  toBytes(): Uint8Array {\n    const out = new Uint8Array(this.pos);\n    memory.copy(out.dataStart, changetype<usize>(this.buf), <usize>this.pos);\n    return out;\n  }\n}\n\nexport class ByteReader {\n  private base: usize;\n  private end: usize;\n  private pos: usize;\n\n  constructor(bytes: Uint8Array) {\n    this.base = bytes.dataStart;\n    this.pos = this.base;\n    this.end = this.base + <usize>bytes.byteLength;\n  }\n\n  /** A reader straight over host-provided memory (the ABI entry points). */\n  static at(ptr: usize, len: i32): ByteReader {\n    const r = new ByteReader(new Uint8Array(0));\n    r.base = ptr;\n    r.pos = ptr;\n    r.end = ptr + <usize>len;\n    return r;\n  }\n\n  get remaining(): i32 {\n    return <i32>(this.end - this.pos);\n  }\n\n  private need(n: usize): void {\n    if (this.pos + n > this.end) abort(\"ByteReader: truncated\");\n  }\n\n  u8(): u8 {\n    this.need(1);\n    const v = load<u8>(this.pos);\n    this.pos += 1;\n    return v;\n  }\n\n  u32(): u32 {\n    this.need(4);\n    const v = load<u32>(this.pos);\n    this.pos += 4;\n    return v;\n  }\n\n  i32(): i32 {\n    this.need(4);\n    const v = load<i32>(this.pos);\n    this.pos += 4;\n    return v;\n  }\n\n  f32(): f32 {\n    this.need(4);\n    const v = load<f32>(this.pos);\n    this.pos += 4;\n    return v;\n  }\n\n  f64(): f64 {\n    this.need(8);\n    const v = load<f64>(this.pos);\n    this.pos += 8;\n    return v;\n  }\n\n  /** n raw bytes, copied. */\n  bytes(n: i32): Uint8Array {\n    this.need(<usize>n);\n    const out = new Uint8Array(n);\n    memory.copy(out.dataStart, this.pos, <usize>n);\n    this.pos += <usize>n;\n    return out;\n  }\n\n  /** u32 length followed by the bytes. */\n  blob(): Uint8Array {\n    const n = <i32>this.u32();\n    return this.bytes(n);\n  }\n\n  /** u32 byte length followed by UTF-8. */\n  str(): string {\n    const n = <i32>this.u32();\n    this.need(<usize>n);\n    const s = String.UTF8.decodeUnsafe(this.pos, <usize>n);\n    this.pos += <usize>n;\n    return s;\n  }\n}\n",
  "host.ts": "// The five host imports (design §5.3) and their ergonomic wrappers. These are the only imports a\n// program may have besides `env.abort`; the sandbox rejects anything else.\n\n// @ts-ignore: decorator\n@external(\"tf\", \"stat\")\ndeclare function tf_stat(path: usize, pathLen: i32): i64;\n// @ts-ignore: decorator\n@external(\"tf\", \"read\")\ndeclare function tf_read(path: usize, pathLen: i32, offset: i32, dst: usize, dstLen: i32): i32;\n// @ts-ignore: decorator\n@external(\"tf\", \"write\")\ndeclare function tf_write(path: usize, pathLen: i32, src: usize, srcLen: i32): i32;\n// @ts-ignore: decorator\n@external(\"tf\", \"list\")\ndeclare function tf_list(prefix: usize, prefixLen: i32, dst: usize, dstLen: i32): i32;\n// @ts-ignore: decorator\n@external(\"tf\", \"log\")\ndeclare function tf_log(src: usize, srcLen: i32): void;\n\n/** Append a line to the task's log (shown in the dashboard's task detail; capped by the host). */\nexport function log(text: string): void {\n  const encoded = String.UTF8.encode(text);\n  tf_log(changetype<usize>(encoded), encoded.byteLength);\n}\n\nexport namespace fs {\n  /** File size in bytes, or -1 if the path does not exist. */\n  export function stat(path: string): i64 {\n    const p = String.UTF8.encode(path);\n    return tf_stat(changetype<usize>(p), p.byteLength);\n  }\n\n  /** A byte range of a file, or null if the path does not exist. */\n  export function readRange(path: string, offset: i32, len: i32): Uint8Array | null {\n    const p = String.UTF8.encode(path);\n    const out = new Uint8Array(len);\n    const got = tf_read(changetype<usize>(p), p.byteLength, offset, out.dataStart, len);\n    if (got < 0) return null;\n    return got == len ? out : out.subarray(0, got);\n  }\n\n  /** The whole file, or null if the path does not exist. */\n  export function read(path: string): Uint8Array | null {\n    const size = stat(path);\n    if (size < 0) return null;\n    if (size == 0) return new Uint8Array(0);\n    return readRange(path, 0, <i32>size);\n  }\n\n  /** Replace the whole file; visible to the next stage once the task's result is accepted. */\n  export function write(path: string, bytes: Uint8Array): bool {\n    const p = String.UTF8.encode(path);\n    return tf_write(changetype<usize>(p), p.byteLength, bytes.dataStart, bytes.byteLength) == 0;\n  }\n\n  /** Paths under a prefix. */\n  export function list(prefix: string): string[] {\n    const p = String.UTF8.encode(prefix);\n    let cap = 4096;\n    for (let attempt = 0; attempt < 8; attempt++) {\n      const buf = new Uint8Array(cap);\n      const need = tf_list(changetype<usize>(p), p.byteLength, buf.dataStart, cap);\n      if (need < 0) return [];\n      if (need <= cap) {\n        if (need == 0) return [];\n        const text = String.UTF8.decodeUnsafe(buf.dataStart, <usize>need);\n        return text.split(\"\\n\");\n      }\n      cap = need;\n    }\n    return [];\n  }\n}\n",
  "index.ts": "// Tabframe SDK for AssemblyScript programs. A program:\n//\n//   import { readRunInput, readPlanInput, stage, done, emit } from \"@tabframe/sdk-as/assembly/index\";\n//   export { alloc } from \"@tabframe/sdk-as/assembly/index\";\n//   export function plan(ptr: usize, len: i32): usize { ... return emit(stage(\"x\").task(bytes).toBytes()); }\n//   export function run(ptr: usize, len: i32): usize { ... return emit(outputBytes); }\n//\n// Compile with: -O3 --runtime stub --maximumMemory <pages> [--noAssert] --path <program>/node_modules\n// (the program package depends on @tabframe/sdk-as; asc resolves the subpath import through that\n// node_modules directory).\n// Allowed imports: tf.stat/read/write/list/log and env.abort. Date.now, Math.random (env.seed),\n// and anything else are rejected by the sandbox. AssemblyScript's Math is compiled to WASM and is\n// deterministic; never write NaN into an output.\nexport { ABI_VERSION, alloc, done, emit, PlanInput, readPlanInput, readRunInput, RunInput, Stage, stage } from \"./abi\";\nexport { Bars, bars } from \"./bars\";\nexport { ByteReader, ByteWriter } from \"./bytes\";\nexport { fs, log } from \"./host\";\nexport { Params, quote, unquote } from \"./params\";\n",
  "params.ts": "// A flat table of key → JSON text (the ABI's `table`). Programs read scalars without a JSON\n// parser; keys are written sorted so identical tables are identical bytes.\nimport { ByteReader, ByteWriter } from \"./bytes\";\n\nexport class Params {\n  keys: string[] = [];\n  values: string[] = [];\n\n  static read(r: ByteReader): Params {\n    const p = new Params();\n    const count = <i32>r.u32();\n    for (let i = 0; i < count; i++) {\n      const key = r.str();\n      const value = r.str();\n      p.set(key, value);\n    }\n    return p;\n  }\n\n  write(w: ByteWriter): void {\n    const n = this.keys.length;\n    const order = new Array<i32>(n);\n    for (let i = 0; i < n; i++) order[i] = i;\n    // Insertion sort by key; tables are small.\n    for (let i = 1; i < n; i++) {\n      const cur = order[i];\n      let j = i - 1;\n      while (j >= 0 && this.keys[order[j]] > this.keys[cur]) {\n        order[j + 1] = order[j];\n        j--;\n      }\n      order[j + 1] = cur;\n    }\n    w.u32(<u32>n);\n    for (let i = 0; i < n; i++) {\n      w.str(this.keys[order[i]]);\n      w.str(this.values[order[i]]);\n    }\n  }\n\n  get size(): i32 {\n    return this.keys.length;\n  }\n\n  has(key: string): bool {\n    return this.indexOf(key) >= 0;\n  }\n\n  indexOf(key: string): i32 {\n    for (let i = 0; i < this.keys.length; i++) if (this.keys[i] == key) return i;\n    return -1;\n  }\n\n  /** The raw JSON text, or null. */\n  raw(key: string): string | null {\n    const i = this.indexOf(key);\n    return i < 0 ? null : this.values[i];\n  }\n\n  /** Set the JSON text directly. */\n  set(key: string, jsonText: string): Params {\n    const i = this.indexOf(key);\n    if (i >= 0) this.values[i] = jsonText;\n    else {\n      this.keys.push(key);\n      this.values.push(jsonText);\n    }\n    return this;\n  }\n\n  setString(key: string, value: string): Params {\n    return this.set(key, quote(value));\n  }\n\n  setI32(key: string, value: i32): Params {\n    return this.set(key, value.toString());\n  }\n\n  setF64(key: string, value: f64): Params {\n    return this.set(key, value.toString());\n  }\n\n  setBool(key: string, value: bool): Params {\n    return this.set(key, value ? \"true\" : \"false\");\n  }\n\n  getString(key: string, fallback: string): string {\n    const v = this.raw(key);\n    if (v === null) return fallback;\n    const text = v as string;\n    if (text.length >= 2 && text.charCodeAt(0) == 34) return unquote(text);\n    return text;\n  }\n\n  getF64(key: string, fallback: f64): f64 {\n    const v = this.raw(key);\n    if (v === null) return fallback;\n    let text = v as string;\n    if (text.length >= 2 && text.charCodeAt(0) == 34) text = unquote(text);\n    if (text.length == 0) return fallback;\n    const n = F64.parseFloat(text);\n    return isNaN(n) ? fallback : n;\n  }\n\n  getI32(key: string, fallback: i32): i32 {\n    const v = this.raw(key);\n    if (v === null) return fallback;\n    let text = v as string;\n    if (text.length >= 2 && text.charCodeAt(0) == 34) text = unquote(text);\n    if (text.length == 0) return fallback;\n    const n = F64.parseFloat(text);\n    if (isNaN(n)) return fallback;\n    return <i32>n;\n  }\n\n  getBool(key: string, fallback: bool): bool {\n    const v = this.raw(key);\n    if (v === null) return fallback;\n    const text = v as string;\n    if (text == \"true\") return true;\n    if (text == \"false\") return false;\n    return fallback;\n  }\n}\n\n/** JSON-quote a string (the escapes JSON requires; everything else verbatim). */\nexport function quote(s: string): string {\n  let out = '\"';\n  for (let i = 0; i < s.length; i++) {\n    const c = s.charCodeAt(i);\n    if (c == 34) out += '\\\\\"';\n    else if (c == 92) out += \"\\\\\\\\\";\n    else if (c == 10) out += \"\\\\n\";\n    else if (c == 13) out += \"\\\\r\";\n    else if (c == 9) out += \"\\\\t\";\n    else if (c < 32) {\n      out += \"\\\\u00\";\n      out += (c >> 4).toString(16);\n      out += (c & 15).toString(16);\n    } else out += String.fromCharCode(c);\n  }\n  return out + '\"';\n}\n\n/** Decode a JSON string literal (the standard escapes, including \\uXXXX). */\nexport function unquote(text: string): string {\n  let out = \"\";\n  const n = text.length - 1;\n  let i = 1;\n  while (i < n) {\n    const c = text.charCodeAt(i);\n    if (c != 92) {\n      out += String.fromCharCode(c);\n      i++;\n      continue;\n    }\n    i++;\n    if (i >= n) break;\n    const e = text.charCodeAt(i);\n    if (e == 110) out += \"\\n\";\n    else if (e == 116) out += \"\\t\";\n    else if (e == 114) out += \"\\r\";\n    else if (e == 98) out += \"\\b\";\n    else if (e == 102) out += \"\\f\";\n    else if (e == 117 && i + 4 < text.length) {\n      const code = <i32>I32.parseInt(text.substring(i + 1, i + 5), 16);\n      out += String.fromCharCode(code);\n      i += 4;\n    } else out += String.fromCharCode(e);\n    i++;\n  }\n  return out;\n}\n"
};

/** The Mandelbrot program as shipped, the editor's prefilled source. */
export const MANDELBROT_SOURCE = "// Mandelbrot: the machine's default program (design §5.6). One stage of 640 tiles per frame, RGBA\n// output with smooth coloring, and a follow-up that advances to the next preset so the default\n// loop never runs out of work. Pure f64 arithmetic plus AssemblyScript's own Math: deterministic\n// everywhere, and no NaN can reach the output.\nimport {\n  ByteReader,\n  ByteWriter,\n  done,\n  emit,\n  Params,\n  readPlanInput,\n  readRunInput,\n  stage,\n} from \"@tabframe/sdk-as/assembly/index\";\n\nexport { alloc } from \"@tabframe/sdk-as/assembly/index\";\n\nconst CANVAS_W: u32 = 2048;\nconst CANVAS_H: u32 = 1280;\nconst TILE: u32 = 64;\nconst COLS: u32 = CANVAS_W / TILE; // 32\nconst ROWS: u32 = CANVAS_H / TILE; // 20\nconst ESCAPE2: f64 = 256.0; // |z|² beyond which the orbit has escaped (R = 16)\nconst CYCLE: f64 = 48.0; // iterations per palette cycle\n\nclass Preset {\n  constructor(\n    public name: string,\n    public cx: f64,\n    public cy: f64,\n    public width: f64,\n    public maxIter: u32,\n    /** Supersampling factor per axis: ss² orbits per pixel. Cost scales with ss², so it is the pacing knob for regions that escape fast. */\n    public ss: u8,\n  ) {}\n}\n\n// Widths are in complex-plane units across the 2048-pixel canvas. Two knobs pace a preset: `ss`\n// (ss² orbits per pixel) and `maxIter`. A tile that is entirely interior and escapes the exact\n// shortcuts costs ss² × 4096 × maxIter iterations whatever the zoom, so the product ss² × maxIter\n// stays at or under about 7 000: a worst-case tile of roughly half a second under Node, which is\n// about two seconds — the scheduler's deadline floor — in a browser tab, where tiles run two to\n// four times slower. The frame's total comes from the boundary work; WP4.3 has the numbers.\nconst PRESETS: Preset[] = [\n  new Preset(\"overview\", -0.75, 0.0, 3.5, 140, 7),\n  new Preset(\"seahorse valley\", -0.7436, 0.1314, 0.003, 13000, 4),\n  new Preset(\"elephant valley\", 0.2755, 0.006, 0.01, 1600, 2),\n  new Preset(\"triple spiral\", -0.088, 0.654, 0.005, 750, 3),\n  new Preset(\"antenna minibrot\", -1.7549, 0.0, 0.01, 750, 3),\n  new Preset(\"double spiral\", -0.1607, 1.0376, 0.0003, 750, 3),\n  new Preset(\"feigenbaum\", -1.4012, 0.0, 0.002, 1600, 2),\n  new Preset(\"julia island\", -1.7688, -0.0017, 0.00001, 1600, 2),\n];\n\nconst PALETTES: string[] = [\"ocean\", \"fire\", \"mono\"];\n\nfunction paletteId(name: string): u8 {\n  for (let i = 0; i < PALETTES.length; i++) if (PALETTES[i] == name) return <u8>i;\n  return 0;\n}\n\n// Centre-out ordering: tiles closest to the canvas centre first, so the image grows from the middle.\nlet tileDist: Float64Array = new Float64Array(0);\n\nfunction byDistance(a: i32, b: i32): i32 {\n  const da = tileDist[a];\n  const db = tileDist[b];\n  if (da < db) return -1;\n  if (da > db) return 1;\n  return a - b;\n}\n\nexport function plan(ptr: usize, len: i32): usize {\n  const input = readPlanInput(ptr, len);\n  let preset = input.params.getI32(\"preset\", 0) % PRESETS.length;\n  if (preset < 0) preset += PRESETS.length;\n  const paletteName = input.params.getString(\"palette\", \"ocean\");\n  const palette = paletteId(paletteName);\n\n  if (input.stage != 0) {\n    const next = new Params();\n    next.setI32(\"preset\", (preset + 1) % PRESETS.length);\n    next.setString(\"palette\", PALETTES[palette]);\n    return emit(done(next));\n  }\n\n  const p = PRESETS[preset];\n  const scale = p.width / <f64>CANVAS_W;\n  const count = <i32>(COLS * ROWS);\n  tileDist = new Float64Array(count);\n  const order = new Array<i32>(count);\n  for (let i = 0; i < count; i++) {\n    const col = <f64>(i % <i32>COLS);\n    const row = <f64>(i / <i32>COLS);\n    const dx = col * <f64>TILE + <f64>TILE / 2.0 - <f64>CANVAS_W / 2.0;\n    const dy = row * <f64>TILE + <f64>TILE / 2.0 - <f64>CANVAS_H / 2.0;\n    tileDist[i] = dx * dx + dy * dy;\n    order[i] = i;\n  }\n  order.sort(byDistance);\n\n  const s = stage(\"render\").canvas(CANVAS_W, CANVAS_H);\n  for (let k = 0; k < count; k++) {\n    const i = order[k];\n    const x = <i32>((i % <i32>COLS) * <i32>TILE);\n    const y = <i32>((i / <i32>COLS) * <i32>TILE);\n    const w = new ByteWriter(64);\n    w.f64(p.cx).f64(p.cy).f64(scale).u32(p.maxIter).u32(CANVAS_W).u32(CANVAS_H).u8(palette).u8(p.ss);\n    w.i32(x).i32(y).i32(<i32>TILE).i32(<i32>TILE);\n    s.taskAt(w.toBytes(), x, y, <i32>TILE, <i32>TILE);\n  }\n  return emit(s.toBytes());\n}\n\n// Palette stops: five RGB anchors, interpolated linearly over t in [0, 1).\nconst STOPS: StaticArray<f64> = [\n  // ocean\n  0.00, 0.02, 0.10, 0.02, 0.40, 0.80, 0.55, 0.90, 1.00, 0.95, 0.98, 0.90, 0.10, 0.30, 0.70,\n  // fire\n  0.05, 0.00, 0.00, 0.60, 0.05, 0.00, 1.00, 0.55, 0.00, 1.00, 0.95, 0.40, 0.30, 0.00, 0.00,\n  // mono\n  0.02, 0.02, 0.02, 0.35, 0.35, 0.35, 0.75, 0.75, 0.75, 1.00, 1.00, 1.00, 0.20, 0.20, 0.20,\n];\n\nfunction channel(palette: i32, stop: i32, c: i32): f64 {\n  return STOPS[palette * 15 + stop * 3 + c];\n}\n\n// Supersampling: ss² orbits per pixel, colors averaged. It antialiases the boundary and spreads\n// compute evenly across tiles, which keeps interior tiles under the scheduler's deadline floor.\n\n/** Packed 0x00RRGGBB for one sample point, or 0 for an interior point. */\nfunction sample(cr: f64, ci: f64, maxIter: u32, palette: i32): u32 {\n  // Two exact interior tests first: a point inside the main cardioid or the period-2 bulb never\n  // escapes, so answering at once costs nothing in output and is what keeps the overview's\n  // interior tiles under the scheduler's deadline (WP4.3). Pure f64 arithmetic, deterministic.\n  const xq = cr - 0.25;\n  const q = xq * xq + ci * ci;\n  if (q * (q + xq) <= 0.25 * ci * ci) return 0;\n  const xp = cr + 1.0;\n  if (xp * xp + ci * ci <= 0.0625) return 0;\n\n  let zr = 0.0;\n  let zi = 0.0;\n  let zr2 = 0.0;\n  let zi2 = 0.0;\n  let n: u32 = 0;\n  // Periodicity check (Brent): an orbit that returns *exactly* to a saved point is periodic and\n  // interior. Exact f64 equality has no false positives and is deterministic across engines, so\n  // the output is unchanged; the only effect is that interior points stop early.\n  let sr = 0.0;\n  let si = 0.0;\n  let check: u32 = 8;\n  let span: u32 = 8;\n  while (n < maxIter && zr2 + zi2 <= ESCAPE2) {\n    zi = 2.0 * zr * zi + ci;\n    zr = zr2 - zi2 + cr;\n    zr2 = zr * zr;\n    zi2 = zi * zi;\n    n++;\n    if (zr == sr && zi == si) return 0;\n    if (n == check) {\n      sr = zr;\n      si = zi;\n      if (span < 4096) span <<= 1;\n      check += span;\n    }\n  }\n  if (n >= maxIter) return 0;\n  // Smooth iteration count; log2 arguments are > 0 because the orbit escaped past R² = 256.\n  const mu = <f64>n + 1.0 - Math.log2(0.5 * Math.log2(zr2 + zi2));\n  let t = mu / CYCLE;\n  t = t - Math.floor(t);\n  const pos = t * 4.0;\n  let stop = <i32>Math.floor(pos);\n  if (stop > 3) stop = 3;\n  const f = pos - <f64>stop;\n  let packed: u32 = 0;\n  for (let c = 0; c < 3; c++) {\n    const a = channel(palette, stop, c);\n    const b = channel(palette, stop + 1, c);\n    const v = <u32>((a + (b - a) * f) * 255.0 + 0.5);\n    packed = (packed << 8) | (v > 255 ? 255 : v);\n  }\n  return packed;\n}\n\nexport function run(ptr: usize, len: i32): usize {\n  const task = readRunInput(ptr, len);\n  const r = new ByteReader(task.input);\n  const cx = r.f64();\n  const cy = r.f64();\n  const scale = r.f64();\n  const maxIter = r.u32();\n  const canvasW = r.u32();\n  const canvasH = r.u32();\n  const palette = <i32>r.u8();\n  let SS = <i32>r.u8();\n  if (SS < 1) SS = 1;\n  if (SS > 8) SS = 8;\n  const tx = r.i32();\n  const ty = r.i32();\n  const tw = r.i32();\n  const th = r.i32();\n\n  const out = new Uint8Array(tw * th * 4);\n  const halfW = <f64>canvasW / 2.0;\n  const halfH = <f64>canvasH / 2.0;\n  const sub = scale / <f64>SS;\n  const samples = <u32>(SS * SS);\n  let o = 0;\n  for (let py = 0; py < th; py++) {\n    for (let px = 0; px < tw; px++) {\n      let rSum: u32 = 0;\n      let gSum: u32 = 0;\n      let bSum: u32 = 0;\n      for (let sy = 0; sy < SS; sy++) {\n        const ci = cy - ((<f64>(ty + py) - halfH) * scale + (<f64>sy + 0.5) * sub);\n        for (let sx = 0; sx < SS; sx++) {\n          const cr = cx + (<f64>(tx + px) - halfW) * scale + (<f64>sx + 0.5) * sub;\n          const packed = sample(cr, ci, maxIter, palette);\n          rSum += (packed >> 16) & 255;\n          gSum += (packed >> 8) & 255;\n          bSum += packed & 255;\n        }\n      }\n      out[o] = <u8>((rSum + samples / 2) / samples);\n      out[o + 1] = <u8>((gSum + samples / 2) / samples);\n      out[o + 2] = <u8>((bSum + samples / 2) / samples);\n      out[o + 3] = 255;\n      o += 4;\n    }\n  }\n  return emit(out);\n}\n";

/** Its manifest, as JSON text. */
export const MANDELBROT_MANIFEST = "{\n  \"name\": \"mandelbrot\",\n  \"view\": \"tiles\",\n  \"persist\": false,\n  \"defaultParams\": { \"preset\": 0, \"palette\": \"ocean\" },\n  \"description\": \"Distributed Mandelbrot render: 640 tiles of 64×64 per 2048×1280 frame, smooth coloring, presets that advance every frame.\"\n}\n";

/** Word count as shipped (three stages over /in/corpus.txt), and its manifest. */
export const WORDCOUNT_SOURCE = "// Word count (design §5.6): three stages over /in/corpus.txt.\n//\n//   stage 0 \"map\"    — mapTasks tasks, each a byte range of the corpus. A task owns the words that\n//                      *start* inside its range: it skips a word straddling its start (the previous\n//                      task owns it) and reads past its end to finish a word straddling its end.\n//                      Output: counts bucketed into PARTITIONS partitions by FNV-1a of the word.\n//   stage 1 \"reduce\" — one task per partition: read every map output under /out/0/, slice this\n//                      partition, sum. Output: the partition sorted by count desc, word asc.\n//   stage 2 \"merge\"  — one task: read the eight reduce outputs, take the global top-K. Exact,\n//                      because partitions are disjoint. Output: the `bars` payload the dashboard draws.\n//   stage 3          — done, no follow-up.\n//\n// The word rule, on bytes: a word is a maximal run of ASCII letters and apostrophes, with leading\n// and trailing apostrophes stripped, lowercased. Everything else — digits, punctuation, whitespace,\n// any non-ASCII byte — separates words. The corpus is normalized at build time so typographic\n// apostrophes are ASCII ones (packages/sdk-as/scripts/corpus.ts). Deterministic by construction:\n// no floating point until the final bar values, and every output is sorted.\nimport {\n  bars,\n  ByteReader,\n  ByteWriter,\n  done,\n  emit,\n  fs,\n  log,\n  readPlanInput,\n  readRunInput,\n  stage,\n} from \"@tabframe/sdk-as/assembly/index\";\n\nexport { alloc } from \"@tabframe/sdk-as/assembly/index\";\n\nconst CORPUS = \"/in/corpus.txt\";\nconst PARTITIONS: i32 = 8;\nconst MAX_MAP_TASKS: i32 = 4096;\nconst MAX_K: i32 = 4096;\n/** Bytes read at a time past a range's end to finish a straddling word. */\nconst TAIL_CHUNK: i32 = 4096;\n\n// ---- the word rule ----------------------------------------------------------------------------\n\nfunction isWordByte(b: u8): bool {\n  return (b >= 97 && b <= 122) || (b >= 65 && b <= 90) || b == 39;\n}\n\nfunction lower(b: u8): u8 {\n  return b >= 65 && b <= 90 ? b + 32 : b;\n}\n\n/** FNV-1a over the word's bytes, modulo the partition count. */\nfunction partitionOf(word: string, partitions: i32): i32 {\n  const bytes = String.UTF8.encode(word);\n  const base = changetype<usize>(bytes);\n  let h: u32 = 2166136261;\n  for (let i = 0; i < bytes.byteLength; i++) {\n    h ^= <u32>load<u8>(base + <usize>i);\n    h *= 16777619;\n  }\n  return <i32>(h % <u32>partitions);\n}\n\nfunction clamp(v: i32, lo: i32, hi: i32): i32 {\n  return v < lo ? lo : v > hi ? hi : v;\n}\n\n// ---- plan ---------------------------------------------------------------------------------------\n\nexport function plan(ptr: usize, len: i32): usize {\n  const input = readPlanInput(ptr, len);\n  const k = clamp(input.params.getI32(\"k\", 25), 1, MAX_K);\n  const mapTasks = clamp(input.params.getI32(\"mapTasks\", 32), 1, MAX_MAP_TASKS);\n\n  if (input.stage == 0) {\n    const size = fs.stat(CORPUS);\n    if (size < 0) abort(\"missing \" + CORPUS);\n    const total = <i32>size;\n    const s = stage(\"map\");\n    for (let i = 0; i < mapTasks; i++) {\n      const start = <i32>((<i64>total * <i64>i) / <i64>mapTasks);\n      const end = <i32>((<i64>total * <i64>(i + 1)) / <i64>mapTasks);\n      const w = new ByteWriter(16);\n      w.u32(<u32>start).u32(<u32>end).u32(<u32>total).u32(<u32>PARTITIONS);\n      s.task(w.toBytes());\n    }\n    return emit(s.toBytes());\n  }\n  if (input.stage == 1) {\n    const s = stage(\"reduce\");\n    for (let p = 0; p < PARTITIONS; p++) {\n      const w = new ByteWriter(8);\n      w.u32(<u32>p).u32(<u32>mapTasks);\n      s.task(w.toBytes());\n    }\n    return emit(s.toBytes());\n  }\n  if (input.stage == 2) {\n    const w = new ByteWriter(8);\n    w.u32(<u32>k).u32(<u32>PARTITIONS);\n    return emit(stage(\"merge\").task(w.toBytes()).toBytes());\n  }\n  return emit(done(null));\n}\n\n// ---- run ----------------------------------------------------------------------------------------\n\nexport function run(ptr: usize, len: i32): usize {\n  const t = readRunInput(ptr, len);\n  if (t.stage == 0) return emit(mapTask(t.input));\n  if (t.stage == 1) return emit(reduceTask(t.input));\n  if (t.stage == 2) return emit(mergeTask(t.input));\n  abort(\"unexpected stage \" + t.stage.toString());\n  return 0;\n}\n\n// ---- stage 0: map -------------------------------------------------------------------------------\n\nfunction mustRead(offset: i32, length: i32): Uint8Array {\n  const bytes = fs.readRange(CORPUS, offset, length);\n  if (bytes === null) abort(\"missing \" + CORPUS);\n  return bytes as Uint8Array;\n}\n\n/**\n * The bytes whose words this task owns, lowercased: the range minus a word straddling its start,\n * plus the rest of a word straddling its end (read in chunks, so a word longer than any buffer is\n * still finished). After the head skip the first byte is a separator or the corpus start, so every\n * word in the result starts inside the range; the tail stops at the first separator, so it adds\n * no word that starts past the end.\n */\nfunction ownedBytes(start: i32, end: i32, total: i32): Uint8Array {\n  const buf: Uint8Array = end > start ? mustRead(start, end - start) : new Uint8Array(0);\n  let headSkip = 0;\n  if (start > 0 && buf.length > 0) {\n    const prev = mustRead(start - 1, 1);\n    if (prev.length == 1 && isWordByte(prev[0])) {\n      while (headSkip < buf.length && isWordByte(buf[headSkip])) headSkip++;\n    }\n  }\n  const tail = new ByteWriter(64);\n  if (buf.length > headSkip && isWordByte(buf[buf.length - 1]) && end < total) {\n    let pos = end;\n    while (pos < total) {\n      const chunk = mustRead(pos, TAIL_CHUNK);\n      if (chunk.length == 0) break;\n      let j = 0;\n      while (j < chunk.length && isWordByte(chunk[j])) j++;\n      tail.raw(j == chunk.length ? chunk : chunk.subarray(0, j));\n      if (j < chunk.length) break;\n      pos += chunk.length;\n    }\n  }\n  const tailBytes = tail.toBytes();\n  const out = new Uint8Array(buf.length - headSkip + tailBytes.length);\n  let o = 0;\n  for (let i = headSkip; i < buf.length; i++) out[o++] = lower(buf[i]);\n  for (let i = 0; i < tailBytes.length; i++) out[o++] = lower(tailBytes[i]);\n  return out;\n}\n\n/** Count the words of a lowercased buffer. */\nfunction countWords(text: Uint8Array, counts: Map<string, u32>): void {\n  const n = text.length;\n  let i = 0;\n  while (i < n) {\n    if (!isWordByte(text[i])) {\n      i++;\n      continue;\n    }\n    let j = i;\n    while (j < n && isWordByte(text[j])) j++;\n    let a = i;\n    let b = j;\n    while (a < b && text[a] == 39) a++;\n    while (b > a && text[b - 1] == 39) b--;\n    if (b > a) {\n      const word = String.UTF8.decodeUnsafe(text.dataStart + <usize>a, <usize>(b - a));\n      counts.set(word, counts.has(word) ? counts.get(word) + 1 : 1);\n    }\n    i = j;\n  }\n}\n\nfunction byWord(a: string, b: string): i32 {\n  return a < b ? -1 : a > b ? 1 : 0;\n}\n\n/**\n * Map output: u32 partitions | partitions × (u32 offset, u32 length) | sections, where a section is\n * u32 count | count × (str word, u32 count) sorted by word. Offsets are from the start of the\n * output, so a reducer reads the header and then exactly its slice.\n */\nfunction mapTask(input: Uint8Array): Uint8Array {\n  const r = new ByteReader(input);\n  const start = <i32>r.u32();\n  const end = <i32>r.u32();\n  const total = <i32>r.u32();\n  const partitions = <i32>r.u32();\n  const counts = new Map<string, u32>();\n  countWords(ownedBytes(start, end, total), counts);\n\n  const words = counts.keys();\n  words.sort(byWord);\n  const sections = new Array<ByteWriter>(partitions);\n  const sizes = new Array<i32>(partitions);\n  for (let p = 0; p < partitions; p++) {\n    sections[p] = new ByteWriter(64);\n    sizes[p] = 0;\n  }\n  for (let i = 0; i < words.length; i++) {\n    const p = partitionOf(words[i], partitions);\n    sections[p].str(words[i]).u32(counts.get(words[i]));\n    sizes[p] += 1;\n  }\n  const out = new ByteWriter(64 + words.length * 24);\n  out.u32(<u32>partitions);\n  let offset = 4 + 8 * partitions;\n  for (let p = 0; p < partitions; p++) {\n    const length = 4 + sections[p].length;\n    out.u32(<u32>offset).u32(<u32>length);\n    offset += length;\n  }\n  for (let p = 0; p < partitions; p++) {\n    out.u32(<u32>sizes[p]);\n    out.raw(sections[p].toBytes());\n  }\n  return out.toBytes();\n}\n\n// ---- stage 1: reduce ----------------------------------------------------------------------------\n\n/** Parallel arrays the sort comparator reads (closures cannot capture locals). */\nlet sortWords: string[] = [];\nlet sortCounts: u32[] = [];\n\nfunction byCountDesc(a: i32, b: i32): i32 {\n  const ca = sortCounts[a];\n  const cb = sortCounts[b];\n  if (ca != cb) return ca > cb ? -1 : 1;\n  return byWord(sortWords[a], sortWords[b]);\n}\n\n/** Add `count × (str word, u32 count)` pairs to the map. */\nfunction addPairs(r: ByteReader, counts: Map<string, u32>): void {\n  const n = <i32>r.u32();\n  for (let i = 0; i < n; i++) {\n    const word = r.str();\n    const c = r.u32();\n    counts.set(word, counts.has(word) ? counts.get(word) + c : c);\n  }\n}\n\n/** Sorted (word, count) pairs: u32 count | count × (str word, u32 count), by count desc then word. */\nfunction sortedPairs(counts: Map<string, u32>): Uint8Array {\n  const order = rankOf(counts);\n  const w = new ByteWriter(16 + order.length * 24);\n  w.u32(<u32>order.length);\n  for (let i = 0; i < order.length; i++) {\n    w.str(sortWords[order[i]]).u32(sortCounts[order[i]]);\n  }\n  return w.toBytes();\n}\n\n/** Fill the sort arrays from the map and return indexes by count desc, word asc. */\nfunction rankOf(counts: Map<string, u32>): i32[] {\n  sortWords = counts.keys();\n  sortCounts = new Array<u32>(sortWords.length);\n  const order = new Array<i32>(sortWords.length);\n  for (let i = 0; i < sortWords.length; i++) {\n    sortCounts[i] = counts.get(sortWords[i]);\n    order[i] = i;\n  }\n  order.sort(byCountDesc);\n  return order;\n}\n\nfunction reduceTask(input: Uint8Array): Uint8Array {\n  const r = new ByteReader(input);\n  const partition = <i32>r.u32();\n  const mapCount = <i32>r.u32();\n  const files = fs.list(\"/out/0/\");\n  if (files.length != mapCount) {\n    abort(\"expected \" + mapCount.toString() + \" map outputs, found \" + files.length.toString());\n  }\n  const counts = new Map<string, u32>();\n  for (let f = 0; f < files.length; f++) {\n    const header = fs.readRange(files[f], 0, 4 + 8 * PARTITIONS);\n    if (header === null) abort(\"missing map output \" + files[f]);\n    const h = new ByteReader(header as Uint8Array);\n    const partitions = <i32>h.u32();\n    if (partitions != PARTITIONS) abort(\"map output with \" + partitions.toString() + \" partitions\");\n    let offset: i32 = 0;\n    let length: i32 = 0;\n    for (let p = 0; p < partitions; p++) {\n      const off = <i32>h.u32();\n      const ln = <i32>h.u32();\n      if (p == partition) {\n        offset = off;\n        length = ln;\n      }\n    }\n    if (length <= 4) continue; // an empty section is just its count\n    const section = fs.readRange(files[f], offset, length);\n    if (section === null) abort(\"missing map output \" + files[f]);\n    addPairs(new ByteReader(section as Uint8Array), counts);\n  }\n  return sortedPairs(counts);\n}\n\n// ---- stage 2: merge -----------------------------------------------------------------------------\n\nfunction mergeTask(input: Uint8Array): Uint8Array {\n  const r = new ByteReader(input);\n  const k = <i32>r.u32();\n  const reduceCount = <i32>r.u32();\n  const files = fs.list(\"/out/1/\");\n  if (files.length != reduceCount) {\n    abort(\"expected \" + reduceCount.toString() + \" reduce outputs, found \" + files.length.toString());\n  }\n  const counts = new Map<string, u32>();\n  for (let f = 0; f < files.length; f++) {\n    const bytes = fs.read(files[f]);\n    if (bytes === null) abort(\"missing reduce output \" + files[f]);\n    addPairs(new ByteReader(bytes as Uint8Array), counts);\n  }\n  const order = rankOf(counts);\n  let total: u64 = 0;\n  for (let i = 0; i < sortCounts.length; i++) total += <u64>sortCounts[i];\n  const top = order.length < k ? order.length : k;\n  const b = bars();\n  for (let i = 0; i < top; i++) b.bar(sortWords[order[i]], <f64>sortCounts[order[i]]);\n  log(\n    sortWords.length.toString() +\n      \" distinct words, \" +\n      total.toString() +\n      \" in total; top \" +\n      top.toString(),\n  );\n  return b.toBytes();\n}\n";
export const WORDCOUNT_MANIFEST = "{\n  \"name\": \"wordcount\",\n  \"view\": \"bars\",\n  \"persist\": false,\n  \"defaultParams\": { \"k\": 25, \"mapTasks\": 32 },\n  \"description\": \"Three-stage word count over Moby-Dick: map byte ranges into eight hashed partitions, reduce each partition, merge into the global top-K.\"\n}\n";

/** The SDK's hello example — the smallest program — and its manifest. */
export const HELLO_SOURCE = "// Hello, text: the smallest Tabframe program. One stage with one task; the task returns a line\n// of text, and the dashboard's `text` view shows it. Read this first, then the Mandelbrot program\n// (tiles, one stage, a follow-up) and word count (three stages over a file).\n//\n//   plan: called once per stage with the stage number and the params; returns the stage's tasks,\n//         or done(next) to end — `next` is a follow-up's params, or null.\n//   run:  called once per task with the task's input bytes; returns the output bytes.\n//\n// Everything a program sees comes in through those bytes and the execution's filesystem: no\n// clock, no randomness, no network, and a task may run on any core, twice, or halfway.\nimport {\n  ByteReader,\n  ByteWriter,\n  done,\n  emit,\n  readPlanInput,\n  readRunInput,\n  stage,\n} from \"@tabframe/sdk-as/assembly/index\";\nexport { alloc } from \"@tabframe/sdk-as/assembly/index\";\n\nexport function plan(ptr: usize, len: i32): usize {\n  const input = readPlanInput(ptr, len);\n  if (input.stage == 0) {\n    // One task; its input carries the greeting's subject from the params (default \"world\").\n    const who = input.params.getString(\"who\", \"world\");\n    const s = stage(\"say\");\n    s.task(new ByteWriter().str(who).toBytes());\n    return emit(s.toBytes());\n  }\n  return emit(done(null)); // no follow-up: the execution ends after stage 0\n}\n\nexport function run(ptr: usize, len: i32): usize {\n  const task = readRunInput(ptr, len);\n  const who = new ByteReader(task.input).str();\n  const text = `hello, ${who} — from task ${task.taskIndex} of ${task.taskCount}`;\n  return emit(Uint8Array.wrap(String.UTF8.encode(text)));\n}\n";
export const HELLO_MANIFEST = "{\"name\":\"hello\",\"view\":\"text\",\"description\":\"One task that says hello; the smallest program there is.\",\"defaultParams\":{\"who\":\"world\"}}";

/** The SDK's README, the editor's guide: what a program is and what it may do. */
export const GUIDE_MARKDOWN = "# @tabframe/sdk-as\n\nThe AssemblyScript SDK for Tabframe programs, and the tooling around programs: the build script,\nthe goldens script, and a minimal Node host.\n\nA program is one WebAssembly module with two entry points and a manifest (design §5). It sees the\nworld only through a per-execution filesystem, has no clock, no randomness, and no network, and\nits API has no failure type: tasks complete, or the execution fails with a program fault.\n\n## Writing a program\n\n```ts\nimport { readRunInput, readPlanInput, stage, done, emit, ByteWriter, ByteReader, Params, fs, log }\n  from \"@tabframe/sdk-as/assembly/index\";\nexport { alloc } from \"@tabframe/sdk-as/assembly/index\";\n\nexport function plan(ptr: usize, len: i32): usize {\n  const input = readPlanInput(ptr, len);          // stage, params, hints\n  if (input.stage == 0) {\n    const s = stage(\"map\").canvas(2048, 1280);\n    for (let i = 0; i < 640; i++) s.taskAt(inputBytes(i), x(i), y(i), 64, 64);   // or s.task(bytes)\n    return emit(s.toBytes());\n  }\n  const next = new Params();                      // optional follow-up params\n  next.setI32(\"preset\", input.params.getI32(\"preset\", 0) + 1);\n  return emit(done(next));                        // or done(null)\n}\n\nexport function run(ptr: usize, len: i32): usize {\n  const t = readRunInput(ptr, len);               // stage, taskIndex, taskCount, input bytes\n  const r = new ByteReader(t.input);\n  // ... compute ...\n  return emit(outputBytes);                       // a Uint8Array\n}\n```\n\n- **Params** are a flat table of key → JSON text. `getString`, `getI32`, `getF64`, `getBool` take a\n  fallback; `raw(key)` gives the JSON text (arrays and objects come through untouched). Setters\n  write JSON. Keys are sorted when written, so equal tables are equal bytes.\n- **Stage** builds what `plan` returns: a name, an optional canvas (for the `tiles` view), and tasks\n  with inline input (≤ 16 KB each, ≤ 4096 tasks, ≤ 1 MB spec) with or without a placement rect.\n- **fs** is the execution's filesystem: `fs.stat(path)` (size or −1), `fs.read(path)` and\n  `fs.readRange(path, offset, len)` (null when absent), `fs.write(path, bytes)` (replaces the whole\n  file; visible to the next stage once the result is accepted), `fs.list(prefix)`. Results land at\n  `/out/<stage>/<task>` automatically; bundle inputs are under `/in/`. Reads cost a round trip\n  each — read whole files or large ranges.\n- **log(text)** appends to the task's log, shown in the dashboard's task detail and capped.\n- **ByteWriter / ByteReader** are for your own compact task inputs (u8/u32/i32/f32/f64, blobs,\n  strings), little-endian.\n\n- **bars()** builds the payload a `bars` program's final task returns:\n  `bars().bar(\"the\", 14529).bar(\"of\", 6620).toBytes()`. Values must be finite (NaN payload bits\n  differ between engines); the builder aborts otherwise. The dashboard decodes it with\n  `decodeBars` from `@tabframe/protocol`.\n\nMulti-stage programs read the previous stage's results as files: `fs.list(\"/out/0/\")` names every\ntask output of stage 0, `fs.readRange` reads a slice of one. See `programs/wordcount` for a\nthree-stage map/reduce/merge that does exactly this.\n\n## Compiling\n\nPrograms depend on `@tabframe/sdk-as` (workspace) and import it by the subpath above; asc resolves\nit through the program's `node_modules`:\n\n```\nasc programs/<name>/assembly/index.ts --outFile programs/<name>/dist/program.wasm \\\n    --path programs/<name>/node_modules --baseDir . -O3 --runtime stub --noAssert --maximumMemory 256\n```\n\n`mise run build:programs` does this for every `programs/*/assembly/index.ts`. The flags matter:\n\n- `--runtime stub` (or `minimal`): a bump allocator with no collector. Every task runs in a fresh\n  instance, so nothing leaks between tasks and nothing needs freeing.\n- `--maximumMemory <pages>`: the sandbox requires a declared memory maximum (64 KiB pages; 256 is\n  16 MiB, the reference value) and rejects modules without one or above its cap.\n- `-O3 --noAssert`: speed; assertions are development aids, not runtime checks.\n\n**Allowed imports:** `tf.stat`, `tf.read`, `tf.write`, `tf.list`, `tf.log`, and `env.abort`.\nAnything else — `Date.now`, `Math.random` (which needs `env.seed`), `console`, WASI — is rejected\nat upload. AssemblyScript's `Math` compiles to WebAssembly and is deterministic across browsers and\nmachines; never write NaN into an output, because NaN payload bits are not.\n\n## Byte formats\n\nThe SDK mirrors `packages/protocol/src/abi.ts` byte for byte; that file is the contract. Magics\n`TFRN` (run input), `TFPL` (plan input), `TFSS` (stage spec), `TFBR` (bars payload); little-endian;\n`str` = u32 length + UTF-8; `table` = u32 count + (str key, str JSON value) with keys sorted. Entry\npoints return a pointer to an 8-byte `{outPtr: u32, outLen: u32}` pair, which `emit` produces.\n\n## Tooling\n\n- `scripts/build-programs.ts` — `mise run build:programs`.\n- `scripts/goldens.ts` — `mise run goldens` writes `programs/<name>/goldens.json` from a single-node\n  run (params from the manifest): per-tile hashes for `tiles` programs, every stage's hashes plus\n  the decoded final payload for staged ones (`--program wordcount`); `--all --sample 16` times every\n  Mandelbrot preset; `--preset N` times one.\n- `scripts/host.ts` — instantiate a module under Node with in-memory files, and `runStaged` to run\n  a whole execution stage by stage the way the control plane would; used by the goldens script,\n  the tests, and (from WP1.9) the churn simulation.\n- `scripts/corpus.ts` — `mise run corpus` fetches and normalizes the word-count corpus into\n  `programs/wordcount/in/corpus.txt` (committed; the script is for reproducibility).\n";
